<?php
declare(strict_types=1);
namespace Hostider\Support\Automation;
use Hostider\Core\{CanonicalJson,Id,Validation};
use Hostider\Core\Http\HttpError;
use Hostider\Core\Security\Principal;
use Hostider\Core\Queue\{Outbox,Queue,Worker};
use Hostider\Support\Advanced\{Common,Operations};
use Hostider\Support\Work\{Eligibility,Store,Calendar,Time};
final readonly class Engine
{
    public function __construct(public Common $m){}
    public function facts(array $t): array
    {
        $db=$this->m->c->db;$w=$db->execute('SELECT * FROM support_work_tickets WHERE ticket_id=?',[$t['id']])->fetch();$sla=$w['sla_status']??'UNCONFIGURED';$hours='__UNAVAILABLE';
        if(($w['policy_id']??null)!==null){$policy=(new Store($this->m->c))->policy($w['policy_id']);$hours=(new Calendar($policy['data']['calendar']))->working(Time::now($db));}
        if($sla==='ACTIVE'){$alert=$db->execute("SELECT a.level FROM support_sla_alerts a JOIN support_sla_clocks c ON c.id=a.clock_id WHERE c.cycle_id=? ORDER BY FIELD(a.level,'BREACH','RISK') LIMIT 1",[$w['cycle_id']])->fetchColumn();$status=$db->execute("SELECT status FROM support_sla_clocks WHERE cycle_id=? ORDER BY FIELD(status,'RUNNING','PAUSED','CANCELLED','COMPLETED') LIMIT 1",[$w['cycle_id']])->fetchColumn();$sla=$alert?:($status?:'UNCONFIGURED');}
        $mail=(bool)$db->execute("SELECT 1 FROM support_mail_sources s JOIN support_events e ON e.id=s.event_id WHERE s.ticket_id=? AND e.kind='CREATED'",[$t['id']])->fetchColumn();return ['department'=>$t['department_id'],'channel'=>$mail?'TEST_ADAPTER':$t['channel'],'priority'=>$t['effective_priority'],'tag'=>array_column($db->execute('SELECT tag FROM support_ticket_tags WHERE ticket_id=? ORDER BY tag LIMIT 32',[$t['id']])->fetchAll(),'tag'),'assigned'=>$w['assignee_id']??null,'business_hours'=>$hours,'sla'=>$sla,'customer_group'=>'__UNAVAILABLE','service_type'=>'__UNAVAILABLE','service_status'=>'__UNAVAILABLE'];
    }
    public function evaluate(array $u,array $s,array $t,array $spec): array
    {
        Ast::rule($spec);$result=Ast::evaluate($spec['when'],$this->facts($t));$actions=[];if($result==='MATCH'){foreach($spec['actions'] as $a){try{(new Operations($this->m))->preflight($u,$s,$t,$a);$actions[]=['kind'=>$a['kind'],'eligible'=>true];if($a['kind']==='state'){$t['status']=$a['value'];}if($a['kind']==='priority'){$t['effective_priority']=$a['value'];}}catch(HttpError $e){$actions[]=['kind'=>$a['kind'],'eligible'=>false,'reason'=>$e->errorCode];}}}return ['result'=>$result,'actions'=>$actions];
    }
    public function simulate(string $ref,array $p): array
    {
        $this->m->gate();Validation::fields($p,['ticket_id','spec'],['ticket_id','spec']);\Hostider\Support\Access::id($p['ticket_id']);$spec=Ast::rule(Common::object($p['spec']));$db=$this->m->c->db;if($db->pdo->inTransaction()){throw new \LogicException('Simulation owns rollback boundary');}$db->pdo->beginTransaction();try{return $this->m->c->identity->withStepUp($ref,'admin',function($u,$s)use($p,$spec){$t=$this->m->access->ticket($u,$s,$p['ticket_id'],'support.automation.manage');return $this->evaluate($u,$s,$t,$spec)+['side_effects'=>false,'redacted'=>true];});}finally{$this->rollbackSimulation();}
    }
    private function rollbackSimulation(): void{if($this->m->c->db->pdo->inTransaction()){$this->m->c->db->pdo->rollBack();}}
    public static function trigger(string $kind,string $name): ?string
    {
        return match($kind){'SUPPORT'=>match($name){'CREATED'=>'ticket_created','CUSTOMER_REPLY'=>'customer_replied','STAFF_REPLY'=>'staff_replied','STATE'=>'state_changed',default=>null},'WORK'=>match($name){'ASSIGNED','UNASSIGNED'=>'assigned','SLA_RISK','SLA_BREACH'=>'sla_risk',default=>null},'INCIDENT'=>'incident_updated','OPERATION'=>in_array($name,['PRIORITY','TAG'],true)?'state_changed':null,default=>null};
    }
    private function source(string $kind,string $id,array $t): array
    {
        $db=$this->m->c->db;$r=match($kind){'SUPPORT'=>$db->execute('SELECT kind,ticket_id,customer_id,ticket_version,trace_id,created_at FROM support_events WHERE id=?',[$id])->fetch(),'WORK'=>$db->execute('SELECT kind,ticket_id,customer_id,ticket_version,trace_id,created_at FROM support_work_events WHERE id=?',[$id])->fetch(),'OPERATION'=>$db->execute('SELECT kind,ticket_id,customer_id,details,trace_id,created_at FROM support_advanced_events WHERE id=?',[$id])->fetch(),'INCIDENT'=>$db->execute("SELECT 'INCIDENT_UPDATED' kind,l.ticket_id,l.customer_id,u.created_at FROM support_incident_updates u JOIN support_incidents i ON i.id=u.incident_id JOIN support_incident_tickets l ON l.incident_id=i.id WHERE u.id=? AND l.ticket_id=? AND l.customer_id=? AND i.department_id=?",[$id,$t['id'],$t['customer_id'],$t['department_id']])->fetch(),default=>false};
        if(!$r||$r['ticket_id']!==$t['id']||$r['customer_id']!==$t['customer_id']||self::trigger($kind,$r['kind'])===null){throw new HttpError(409,'RULE_SOURCE_INVALID');}if($kind==='OPERATION'){$r['ticket_version']=json_decode($r['details'],true,16,JSON_THROW_ON_ERROR)['version']??null;}return $r;
    }
    /** Trusted DB adapter only; HTTP never accepts an event or causation envelope. */
    public function stage(string $kind,string $source,array $t,?array $parent=null,?string $rule=null): ?string
    {
        $this->m->gate();$db=$this->m->c->db;$db->requireTransaction();$r=$this->source($kind,$source,$t);$trigger=self::trigger($kind,$r['kind']);$snapshot=$db->execute('SELECT r.id FROM support_rule_heads h JOIN support_rule_revisions r ON r.id=h.revision_id WHERE h.department_id=? AND h.customer_id=? AND r.enabled=TRUE ORDER BY r.ordering,h.id LIMIT 17',[$t['department_id'],$t['customer_id']])->fetchAll();$ids=[];foreach($snapshot as $x){$spec=json_decode($db->execute('SELECT spec FROM support_rule_revisions WHERE id=?',[$x['id']])->fetchColumn(),true,32,JSON_THROW_ON_ERROR);if($spec['trigger']===$trigger){$ids[]=$x['id'];}}if(count($snapshot)>16){throw new HttpError(409,'RULE_SCOPE_LIMIT');}if($ids===[]){return null;}$old=$db->execute('SELECT id FROM support_automation_events WHERE source_kind=? AND source_id=? AND ticket_id=?',[$kind,$source,$t['id']])->fetchColumn();if($old){return $old;}
        $depth=$parent===null?0:(int)$parent['depth']+1;$chain=$parent===null?[]:json_decode($parent['chain_json'],true,16,JSON_THROW_ON_ERROR);if($rule!==null){$chain[]=$rule;}if($depth>4){return null;}$id=Id::uuid();$trace=$parent['correlation_id']??($r['trace_id']??Id::uuid());$cause=$parent['id']??$source;$version=$r['ticket_version']??$t['version'];$db->execute('INSERT INTO support_automation_events(id,source_kind,source_id,ticket_id,customer_id,department_id,trigger_name,source_ticket_version,causation_id,correlation_id,parent_id,depth,chain_json,rule_snapshot) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$kind,$source,$t['id'],$t['customer_id'],$t['department_id'],$trigger,$version,$cause,$trace,$parent['id']??null,$depth,CanonicalJson::encode($chain),CanonicalJson::encode($ids)]);(new Outbox($db,new Queue($db)))->append($id,'support.automation',$t['id'],['event_uuid'=>$id,'ticket_id'=>$t['id']],$trace,$cause);return $id;
    }
    public function seed(int $max=25): array
    {
        $this->m->gate();\Hostider\Support\Work\Policy::integer($max,1,25);$db=$this->m->c->db;$count=0;$deadline=hrtime(true)+20_000_000_000;
        foreach(['SUPPORT','WORK','OPERATION','INCIDENT'] as $kind){if($count>=$max||hrtime(true)>$deadline||memory_get_usage(true)>64*1024*1024){break;}$table=match($kind){'SUPPORT'=>'support_events','WORK'=>'support_work_events','OPERATION'=>'support_advanced_events',default=>'support_incident_updates'};$join=$kind==='INCIDENT'?' JOIN support_incident_tickets l ON l.incident_id=e.incident_id JOIN support_tickets t ON t.id=l.ticket_id':' JOIN support_tickets t ON t.id=e.ticket_id';$allowed=match($kind){'SUPPORT'=>"e.kind IN ('CREATED','CUSTOMER_REPLY','STAFF_REPLY','STATE')",'WORK'=>"e.kind IN ('ASSIGNED','UNASSIGNED','SLA_RISK','SLA_BREACH')",'OPERATION'=>"e.kind IN ('PRIORITY','TAG')",default=>'1=1'};
            $triggerSql=match($kind){'SUPPORT'=>"CASE e.kind WHEN 'CREATED' THEN 'ticket_created' WHEN 'CUSTOMER_REPLY' THEN 'customer_replied' WHEN 'STAFF_REPLY' THEN 'staff_replied' ELSE 'state_changed' END",'WORK'=>"CASE WHEN e.kind IN ('ASSIGNED','UNASSIGNED') THEN 'assigned' ELSE 'sla_risk' END",'OPERATION'=>"'state_changed'",default=>"'incident_updated'"};
            $filter=" AND JSON_UNQUOTE(JSON_EXTRACT(r.spec,'$.trigger'))=".$triggerSql;
            $rows=$db->execute('SELECT e.id source,t.id ticket FROM '.$table.' e'.$join.' WHERE '.$allowed.' AND EXISTS (SELECT 1 FROM support_rule_heads h JOIN support_rule_revisions r ON r.id=h.revision_id WHERE h.department_id=t.department_id AND h.customer_id=t.customer_id AND r.enabled=TRUE AND r.created_at<=e.created_at'.$filter.') AND NOT EXISTS (SELECT 1 FROM support_automation_events a WHERE a.source_kind=? AND a.source_id=e.id AND a.ticket_id=t.id) ORDER BY e.created_at,e.id,t.id LIMIT '.($max-$count),[$kind])->fetchAll();foreach($rows as $r){if(hrtime(true)>$deadline){break;}$db->transaction(function()use($r,$kind){$this->m->access->department($this->m->c->db->execute('SELECT department_id FROM support_tickets WHERE id=?',[$r['ticket']])->fetchColumn());$t=$this->m->c->db->execute('SELECT * FROM support_tickets WHERE id=? FOR UPDATE',[$r['ticket']])->fetch();$this->stage($kind,$r['source'],$t);});++$count;}}
        return ['staged'=>$count,'limit'=>$max,'test_only'=>true];
    }
    private function bound(array $p): array
    {
        Validation::fields($p,['event_uuid','ticket_id'],['event_uuid','ticket_id']);foreach($p as $v){\Hostider\Support\Access::id($v);}$db=$this->m->c->db;$e=$db->execute('SELECT * FROM support_automation_events WHERE id=? AND ticket_id=?',[$p['event_uuid'],$p['ticket_id']])->fetch();$o=$db->execute('SELECT * FROM outbox_events WHERE event_uuid=?',[$p['event_uuid']])->fetch();$j=$db->execute('SELECT * FROM jobs WHERE dedupe_key=?',['outbox:'.$p['event_uuid']])->fetch();$json=CanonicalJson::encode($p);if(!$e||!$o||!$j||$o['published_at']===null||$o['event_type']!=='support.automation'||$j['job_type']!=='support.automation'||$o['aggregate_id']!==$p['ticket_id']||$o['correlation_id']!==$e['correlation_id']||$o['causation_id']!==$e['causation_id']||$j['correlation_id']!==$e['correlation_id']||CanonicalJson::fromJson($o['payload'])!==$json||CanonicalJson::fromJson($j['payload'])!==$json||!hash_equals($j['payload_fingerprint']??'',hash('sha256',$json))){throw new HttpError(409,'RULE_JOB_BINDING_INVALID');}return $e;
    }
    private function execution(array $e,array $r,string $result,string $reason,?string $id=null): string
    {
        $id??=Id::uuid();$this->m->c->db->execute("INSERT INTO support_rule_executions VALUES (?,?,?,?,?,?,?,?,'SYSTEM_RULE',?,?,UTC_TIMESTAMP(6))",[$id,$e['id'],$r['id'],$r['rule_id'],$e['source_ticket_version'],$e['causation_id'],$e['correlation_id'],$r['sponsor_id'],$result,$reason]);$this->m->event($e['department_id'],$id,$result,new Principal('support-rule',[],customerId:$e['customer_id']),$e['correlation_id'],['rule_revision'=>$r['id'],'reason'=>$reason],['id'=>$e['ticket_id'],'customer_id'=>$e['customer_id']],$r['sponsor_id'],$id,$e['causation_id']);return $id;
    }
    public function consume(array $p): string
    {
        $this->m->gate();$db=$this->m->c->db;$db->execute('SET SESSION innodb_lock_wait_timeout=2');$deadline=hrtime(true)+5_000_000_000;return $db->transaction(function()use($p,$db,$deadline){(new Eligibility($this->m->c))->fence();$e=$this->bound($p);$this->m->access->department($e['department_id']);$t=$db->execute('SELECT * FROM support_tickets WHERE id=? FOR UPDATE',[$e['ticket_id']])->fetch();$r=$this->source($e['source_kind'],$e['source_id'],$t);if($t['customer_id']!==$e['customer_id']||$t['department_id']!==$e['department_id']||self::trigger($e['source_kind'],$r['kind'])!==$e['trigger_name']||($e['source_kind']!=='INCIDENT'&&(int)$r['ticket_version']!==(int)$e['source_ticket_version'])){throw new HttpError(409,'RULE_SOURCE_BINDING_INVALID');}
            if($db->execute("SELECT 1 FROM inbox_events WHERE consumer='support.automation.v1' AND event_uuid=?",[$e['id']])->fetchColumn()){return 'SUCCEEDED';}$db->execute("INSERT INTO inbox_events(consumer,event_uuid) VALUES ('support.automation.v1',?)",[$e['id']]);$stale=(int)$t['version']!==(int)$e['source_ticket_version'];$chain=json_decode($e['chain_json'],true,16,JSON_THROW_ON_ERROR);$ids=json_decode($e['rule_snapshot'],true,16,JSON_THROW_ON_ERROR);foreach($ids as $rid){$revision=$db->execute('SELECT r.*,h.department_id,h.customer_id,h.revision_id FROM support_rule_revisions r JOIN support_rule_heads h ON h.id=r.rule_id WHERE r.id=?',[$rid])->fetch();if(!$revision||$revision['department_id']!==$e['department_id']||$revision['customer_id']!==$e['customer_id']){throw new HttpError(409,'RULE_REVISION_BINDING_INVALID');}$spec=Ast::rule(json_decode($revision['spec'],true,32,JSON_THROW_ON_ERROR));
                if(hrtime(true)>$deadline){$this->execution($e,$revision,'SKIPPED','EVALUATION_BUDGET');continue;}if(in_array($revision['rule_id'],$chain,true)||(int)$e['depth']>=4){$this->execution($e,$revision,'LOOP_BLOCKED','CHAIN_LIMIT');continue;}if($stale||$revision['revision_id']!==$rid){$this->execution($e,$revision,'SKIPPED',$stale?'STALE_TICKET':'STALE_RULE');continue;}$db->execute('SAVEPOINT rule_atomic');try{$ref=$db->execute('SELECT native_reference FROM identity_sessions WHERE id=?',[$revision['session_id']])->fetchColumn();if(!is_string($ref)){throw new HttpError(403,'RULE_SPONSOR_REVOKED');}$this->m->c->identity->withStepUp($ref,'admin',function($u,$s)use($e,$revision,$spec,$ref,$db,$deadline){if($u['id']!==$revision['sponsor_id']||(int)$u['identity_version']!==(int)$revision['identity_version']){throw new HttpError(403,'RULE_SPONSOR_REVOKED');}$t=$this->m->access->ticket($u,$s,$e['ticket_id'],'support.automation.manage');$eval=$this->evaluate($u,$s,$t,$spec);if($eval['result']!=='MATCH'){$this->execution($e,$revision,$eval['result'],'PREDICATE');return;}$this->m->event($t['department_id'],$revision['id'],'MATCH',new Principal('support-rule',[],customerId:$t['customer_id']),$e['correlation_id'],[],$t,$u['id'],null,$e['causation_id']);foreach($eval['actions'] as $a){if(!$a['eligible']){throw new HttpError(409,$a['reason']);}}$ex=$this->execution($e,$revision,'APPLIED','CANONICAL_ACTIONS');foreach($spec['actions'] as $n=>$a){if(hrtime(true)>$deadline){throw new HttpError(409,'RULE_EVALUATION_BUDGET');}$t=$this->m->access->ticket($u,$s,$e['ticket_id']);$effect=(new Operations($this->m))->apply($ref,$u,$s,$t,$a,$e['correlation_id'],$ex,$e['id']);$db->execute('INSERT INTO support_rule_action_results VALUES (?,?,?,?,?,?,?,?)',[Id::uuid(),$ex,$e['id'],$revision['id'],$n,$a['kind'],$effect['changed']?'APPLIED':'SKIPPED',$effect['effect_id']]);if($effect['changed']&&in_array($a['kind'],['state','assign','priority','tag'],true)){$next=$this->m->access->ticket($u,$s,$t['id']);$kind=in_array($a['kind'],['priority','tag'],true)?'OPERATION':($a['kind']==='state'?'SUPPORT':'WORK');$table=$kind==='SUPPORT'?'support_events':($kind==='WORK'?'support_work_events':'support_advanced_events');$event=$kind==='OPERATION'?$effect['effect_id']:$db->execute('SELECT id FROM '.$table.' WHERE ticket_id=? AND ticket_version=? AND kind=? ORDER BY created_at DESC,id DESC LIMIT 1',[$t['id'],$next['version'],$kind==='WORK'?($a['value']===null?'UNASSIGNED':'ASSIGNED'):'STATE'])->fetchColumn();if(is_string($event)){$this->stage($kind,$event,$next,$e,$revision['rule_id']);}}}});
                }catch(HttpError $error){if(!$db->pdo->inTransaction()){throw $error;}$db->execute('ROLLBACK TO SAVEPOINT rule_atomic');$this->execution($e,$revision,in_array($error->status,[401,403,404],true)?'SKIPPED':'FAILED',in_array($error->status,[401,403,404],true)?'AUTHORIZATION_UNAVAILABLE':$error->errorCode);}finally{if($db->pdo->inTransaction()){$db->execute('RELEASE SAVEPOINT rule_atomic');}}}
            return 'SUCCEEDED';});
    }
    public function held(array $p): string
    {
        $this->m->gate();Validation::fields($p,['event_uuid','ticket_id','execution_id'],['event_uuid','ticket_id','execution_id']);foreach($p as $v){\Hostider\Support\Access::id($v);}$db=$this->m->c->db;return $db->transaction(function()use($p,$db){$r=$db->execute("SELECT n.id,x.correlation_id,x.event_uuid FROM support_staff_held n JOIN support_rule_executions x ON x.id=n.execution_id JOIN support_automation_events e ON e.id=x.event_uuid JOIN support_tickets t ON t.id=n.ticket_id AND t.customer_id=n.customer_id WHERE n.id=? AND n.ticket_id=? AND n.execution_id=? AND n.status='HELD' AND e.ticket_id=n.ticket_id AND e.customer_id=n.customer_id",[$p['event_uuid'],$p['ticket_id'],$p['execution_id']])->fetch();$o=$db->execute('SELECT * FROM outbox_events WHERE event_uuid=?',[$p['event_uuid']])->fetch();$j=$db->execute('SELECT * FROM jobs WHERE dedupe_key=?',['outbox:'.$p['event_uuid']])->fetch();$json=CanonicalJson::encode($p);if(!$r||!$o||!$j||$o['published_at']===null||$o['event_type']!=='support.advanced.held'||$j['job_type']!=='support.advanced.held'||$o['aggregate_id']!==$p['ticket_id']||$o['correlation_id']!==$r['correlation_id']||$j['correlation_id']!==$r['correlation_id']||$o['causation_id']!==$r['event_uuid']||CanonicalJson::fromJson($o['payload'])!==$json||CanonicalJson::fromJson($j['payload'])!==$json||!hash_equals($j['payload_fingerprint']??'',hash('sha256',$json))){throw new HttpError(409,'RULE_HELD_BINDING_INVALID');}$db->execute("INSERT INTO inbox_events(consumer,event_uuid) VALUES ('support.advanced.held.v1',?) ON DUPLICATE KEY UPDATE event_uuid=VALUES(event_uuid)",[$p['event_uuid']]);return 'SUCCEEDED';});
    }
    public function register(Worker $w): void{$w->register('support.automation',fn(array $p): string=>$this->consume($p));$w->register('support.advanced.held',fn(array $p): string=>$this->held($p));}
}
